# a scope-checked tool call
REQUIRED_SCOPE = "orders:read"

def call_tool(identity, tool_name, args):
    if REQUIRED_SCOPE not in identity.scopes:
        raise PermissionError(f"missing scope {REQUIRED_SCOPE}")
    return tools[tool_name](args)

def get_ticket(identity, ticket_id):
    ticket = db.tickets.find_one({"id": ticket_id})
    if ticket.owner_team not in identity.teams:
        raise PermissionError("ticket not in caller's team")
    return ticket

def dispatch(identity, tool_name, args):
    required = TOOL_SCOPES[tool_name]
    if required not in identity.scopes:
        deny(identity, tool_name)
        raise PermissionError(f"{tool_name} requires scope {required}")
    allow(identity, tool_name)
    return TOOLS[tool_name](args)

# a small role based model is often enough to start
ROLES = {
    "viewer": {"read"},
    "editor": {"read", "write"},
    "admin": {"read", "write", "delete"},
}

# deny by default
def is_allowed(identity, tool_name):
    return tool_name in identity.scopes  # absence means denied, not allowed

def session_scopes(identity, session):
    if session.client_trusted:
        return identity.scopes
    return [s for s in identity.scopes if s.endswith(":read")]

def get_ticket_safe(identity, ticket_id):
    ticket = db.tickets.find_one({"id": ticket_id})
    if not ticket or ticket.owner_team not in identity.teams:
        raise NotFoundError("ticket not found")  # same error either way
    return ticket

ROLE_SCOPES = {
    "viewer": {"deploy:read"},
    "releaser": {"deploy:read", "deploy:trigger", "deploy:rollback"},
}

def authorize(identity, tool_name):
    required = TOOL_SCOPE[tool_name]
    if required not in ROLE_SCOPES.get(identity.role, set()):
        log_denied(identity, tool_name)
        raise PermissionError(f"role {identity.role} cannot use {tool_name}")
    log_allowed(identity, tool_name)
